import { UnorderedList, Grid, Column } from '@carbon/react';
import { clsx } from 'clsx';
import PropTypes from 'prop-types';
import 'react';
import { withPrefix } from '../utils.js';
import { LiConsumer } from './li.js';
import { jsx } from 'react/jsx-runtime';

/**
 * For MDX files, steer away from using JSX components
 * for lists in favor of standard markdown syntax.
 *
 *```
 * - Lorem ipsum dolor sit amet, consectetur adipiscing elit.
 * - dolore magna aliqua. Pharetra massa massa ultricies mi quis.
 * - Massa eget egestas purus viverra accumsan in nisl nisi.
 * - Dolor sit amet consectetur adipiscing.
 * ```
 */
const UL = ({
  children,
  className,
  ...rest
}) => {
  return /*#__PURE__*/jsx(LiConsumer, {
    children: value => {
      if (value.hasListItemParent) {
        return /*#__PURE__*/jsx(UnorderedList, {
          isExpressive: true,
          className: clsx(className, withPrefix('list'), withPrefix('ul')),
          nested: true,
          ...rest,
          children: children
        });
      } else {
        return /*#__PURE__*/jsx(Grid, {
          className: withPrefix('list-container'),
          children: /*#__PURE__*/jsx(Column, {
            sm: 4,
            md: 8,
            lg: 8,
            children: /*#__PURE__*/jsx(UnorderedList, {
              isExpressive: true,
              className: clsx(className, withPrefix('list'), withPrefix('ul')),
              ...rest,
              children: children
            })
          })
        });
      }
    }
  });
};
UL.propTypes = {
  /**
   * Child LI elements
   */
  children: PropTypes.oneOfType([PropTypes.arrayOf(PropTypes.element.isRequired).isRequired, PropTypes.element.isRequired]).isRequired,
  /**
   * Specify optional className for container element
   */
  className: PropTypes.string
};

export { UL };
