import { OrderedList, Grid, Column } from '@carbon/react';
import { clsx } from 'clsx';
import PropTypes from 'prop-types';
import 'react';
import { withPrefix } from '../utils.js';
import { LiConsumer } from './li.js';
import { jsx } from 'react/jsx-runtime';

/**
 * For MDX files, steer away from using JSX components
 * for lists in favor of standard markdown syntax.
 *
 *```
 * 1. First ordered list item
 * 1. In markdown, the actual numbers don’t matter, just that it’s a number
 * 2. In markdown, the actual numbers don’t matter, just that it’s a number
 * ```
 */
const OL = ({
  children,
  className,
  ...rest
}) => {
  return /*#__PURE__*/jsx(LiConsumer, {
    children: value => {
      if (value.hasListItemParent) {
        return /*#__PURE__*/jsx(OrderedList, {
          isExpressive: true,
          className: clsx(className, withPrefix('list'), withPrefix('ol')),
          nested: true,
          ...rest,
          children: children
        });
      } else {
        return /*#__PURE__*/jsx(Grid, {
          className: withPrefix('list-container'),
          children: /*#__PURE__*/jsx(Column, {
            sm: 4,
            md: 8,
            lg: 8,
            children: /*#__PURE__*/jsx(OrderedList, {
              isExpressive: true,
              className: clsx(className, withPrefix('list'), withPrefix('ol')),
              ...rest,
              children: children
            })
          })
        });
      }
    }
  });
};
OL.propTypes = {
  /**
   * Child LI elements
   */
  children: PropTypes.oneOfType([PropTypes.arrayOf(PropTypes.element.isRequired).isRequired, PropTypes.element.isRequired]).isRequired,
  /**
   * Specify optional className for container element
   */
  className: PropTypes.string
};

export { OL };
